import z3
import itertools

weeks = 5
players = 35
groups = 7

solver = z3.Solver()

group = [[z3.Int(f'g{w}_{p}') for p in range(players)] for w in range(weeks)]

for w in range(weeks):
    for p in range(players):
        solver.add(group[w][p] >= 0, group[w][p] < groups)

for w in range(weeks):
    for g in range(groups):
        solver.add(z3.Sum([group[w][p] == g for p in range(players)]) == 5)

for p1 in range(players):
    for p2 in range(p1 + 1, players):
        solver.add(z3.Sum([group[w][p1] == group[w][p2] for w in range(weeks)]) <= 1)

# Symmetry breaking
for p in range(players):
    solver.add(group[0][p] == p // 5)

for w in range(1, weeks):
    solver.add(group[w][0] == 0)

# Add more symmetry breaking: order the groups by the smallest player in each group for each week
for w in range(1, weeks):
    smallest = [z3.Int(f'small{w}_{g}') for g in range(groups)]
    for g in range(groups):
        solver.add(smallest[g] == z3.Min([z3.If(group[w][p] == g, p, 100) for p in range(players)]))
    for g in range(groups - 1):
        solver.add(smallest[g] < smallest[g+1])

solver.set('timeout', 60000)
result = solver.check()
print(str(result))

if result == z3.sat:
    m = solver.model()
    sol = [int(m.evaluate(group[w][p]).as_long()) for w in range(weeks) for p in range(players)]
    print(sol)
else:
    print("UNSAT or timeout")

